function snapshotState(state) {
  const copy = {};
  for (const key of Object.keys(state)) {
    if (key === 'history' || key === 'undo') continue;
    copy[key] = state[key];
  }
  return JSON.parse(JSON.stringify(copy));
}

function pushHistory(state, snapshot) {
  state.history.push(snapshot);
  if (state.history.length > MAX_UNDO) {
    state.history.splice(0, state.history.length - MAX_UNDO);
  }
  state.undo = state.history.length;
}

function undo(state, rng) {
  if (state.history.length === 0) {
    state.undo = 0;
    return false;
  }
  const snapshot = state.history.pop();
  for (const key of Object.keys(snapshot)) {
    state[key] = snapshot[key];
  }
  state.undo = state.history.length;
  rng.state = state.rngState >>> 0;
  return true;
}
```

